mapper.select:
SELECT m2m.m2mid, m2m.branchid, m2m.memberid, m2m.question, m2m.answer, m2m.status, DATE_FORMAT(m2m.regdate, '%Y-%m-%d %H:%i:%s') regdate, DATE_FORMAT(m2m.findate, '%Y-%m-%d %H:%i:%s') findate FROM ttokssaemdb.m2m m2m
AND m2m.memberid = #{memberid}
ORDER BY m2mid desc
LIMIT ${length} OFFSET ${start}

mapper.update:
UPDATE ttokssaemdb.m2m
SET
  question = #{question}
WHERE
  m2mid = #{m2mid}
